import { z } from "zod";
const zObj = z.object({ url: z.string() }).passthrough();
export function PageParams(define) {
    return define("PageParams")
        .props(z.object({
        initialVal: zObj,
    }))
        .shared({
        val: zObj,
    })
        .defaults((props) => ({
        val: props.initialVal,
    }))
        .exposeSetter({ val: true })
        .render((props) => ({}));
}
